// The app's logic and data. No page code here: ui.js uses these functions and tests/app.test.js tests them.

const STORAGE_KEY = "foundry-app";

/** Round to 2 decimals. */
function roundCents(value) {
  return Math.round(value * 100) / 100;
}

/** Check the inputs; returns { valid, message }. */
function validateInputs(bill, tipPercent, people) {
  if (typeof bill !== "number" || !Number.isFinite(bill) || bill <= 0) {
    return { valid: false, message: "Please enter a bill amount greater than zero." };
  }
  if (typeof people !== "number" || !Number.isFinite(people) || people < 1 || !Number.isInteger(people)) {
    return { valid: false, message: "Please enter at least 1 person." };
  }
  if (typeof tipPercent !== "number" || !Number.isFinite(tipPercent) || tipPercent < 0) {
    return { valid: false, message: "Tip percentage can't be negative." };
  }
  return { valid: true, message: "" };
}

/** Tip amount in dollars. */
function calculateTip(bill, tipPercent) {
  return roundCents(bill * tipPercent / 100);
}

/** Tip, total and per-person share. */
function calculateSplit(bill, tipPercent, people, roundUp) {
  const tip = calculateTip(bill, tipPercent);
  if (roundUp) {
    const perPerson = Math.ceil(roundCents((bill + tip) / people));
    return { tip, total: roundCents(perPerson * people), perPerson };
  }
  const total = roundCents(bill + tip);
  return { tip, total, perPerson: roundCents(total / people) };
}

/** Read saved data, or return the fallback when nothing is saved (or storage is unavailable). */
function loadData(fallback) {
  try {
    const raw = globalThis.localStorage && globalThis.localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

/** Save data so it is still there next time the app is opened. */
function saveData(data) {
  try {
    if (globalThis.localStorage) globalThis.localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch {
    // storage full or blocked: the app keeps working, it just won't remember
  }
}

// Keep this line last. List every function ui.js or the tests use.
if (typeof module !== "undefined") module.exports = { roundCents, validateInputs, calculateTip, calculateSplit, loadData, saveData };

