// The app's logic and data. No page code here: ui.js uses these functions and tests/app.test.js tests them.

const STORAGE_KEY = "foundry-app";

/** Read saved data, or return the fallback when nothing is saved (or storage is unavailable). */
function loadData(fallback) {
  try {
    const raw = globalThis.localStorage && globalThis.localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

/** Save data so it is still there next time the app is opened. */
function saveData(data) {
  try {
    if (globalThis.localStorage) globalThis.localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch {
    // storage full or blocked: the app keeps working, it just won't remember
  }
}

let idCounter = 0;

function emptyData() {
  return { habits: [], checks: {} };
}

function fmt(d) {
  const p = (n) => String(n).padStart(2, "0");
  return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate());
}

function todayString() {
  return fmt(new Date());
}

function addHabit(data, name) {
  const trimmed = String(name == null ? "" : name).trim();
  if (!trimmed) return data;
  let id;
  do {
    idCounter += 1;
    id = "h" + Date.now() + (idCounter > 1 ? "_" + idCounter : "");
  } while (data.habits.some((h) => h.id === id));
  return {
    habits: data.habits.concat([{ id, name: trimmed }]),
    checks: Object.assign({}, data.checks, { [id]: [] }),
  };
}

function isChecked(data, habitId, dateStr) {
  const list = data.checks[habitId];
  return Array.isArray(list) && list.includes(dateStr);
}

function toggleCheck(data, habitId, dateStr) {
  if (!data.habits.some((h) => h.id === habitId)) return data;
  const list = data.checks[habitId] || [];
  const next = list.includes(dateStr) ? list.filter((d) => d !== dateStr) : list.concat([dateStr]);
  return { habits: data.habits, checks: Object.assign({}, data.checks, { [habitId]: next }) };
}

function shiftDay(dateStr, delta) {
  const [y, m, d] = dateStr.split("-").map(Number);
  return fmt(new Date(y, m - 1, d + delta));
}

function getStreak(data, habitId, todayStr) {
  let day = todayStr;
  if (!isChecked(data, habitId, day)) {
    day = shiftDay(todayStr, -1);
    if (!isChecked(data, habitId, day)) return 0;
  }
  let n = 0;
  while (isChecked(data, habitId, day)) {
    n += 1;
    day = shiftDay(day, -1);
  }
  return n;
}

// Keep this line last. List every function ui.js or the tests use.
if (typeof module !== "undefined") module.exports = { loadData, saveData, emptyData, todayString, addHabit, toggleCheck, isChecked, getStreak };

