const test = require("node:test");
const assert = require("node:assert/strict");
const app = require("../app.js");

test("loadData returns the fallback when nothing is saved", () => {
  assert.deepEqual(app.loadData([]), []);
});

test("addHabit trims, ignores empty, and toggleCheck toggles", () => {
  const d0 = app.emptyData();
  assert.equal(app.addHabit(d0, "   "), d0);
  const d1 = app.addHabit(d0, "  Read ");
  assert.equal(d1.habits[0].name, "Read");
  const id = d1.habits[0].id;
  const d2 = app.toggleCheck(d1, id, "2024-05-01");
  assert.ok(app.isChecked(d2, id, "2024-05-01"));
  assert.ok(!app.isChecked(app.toggleCheck(d2, id, "2024-05-01"), id, "2024-05-01"));
  assert.equal(app.toggleCheck(d1, "nope", "2024-05-01"), d1);
});

test("getStreak counts back from today or yesterday and stops at gaps", () => {
  let d = app.addHabit(app.emptyData(), "Run");
  const id = d.habits[0].id;
  for (const day of ["2024-02-27", "2024-02-28", "2024-02-29", "2024-03-01"]) d = app.toggleCheck(d, id, day);
  assert.equal(app.getStreak(d, id, "2024-03-01"), 4);
  assert.equal(app.getStreak(d, id, "2024-03-02"), 4);
  assert.equal(app.getStreak(d, id, "2024-03-03"), 0);
  d = app.toggleCheck(d, id, "2024-02-28");
  assert.equal(app.getStreak(d, id, "2024-03-01"), 2);
});

