// Connects the page (index.html) to the logic in app.js.
(function () {
  var data = loadData() || emptyData();
  var input = document.getElementById('habit-input');
  var btn = document.getElementById('add-habit-btn');
  var list = document.getElementById('habit-list');
  var empty = document.getElementById('empty-state');

  function render() {
    var today = todayString();
    list.innerHTML = '';
    empty.hidden = data.habits.length > 0;
    data.habits.forEach(function (h) {
      var li = document.createElement('li');
      var cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.id = 'check-' + h.id;
      cb.checked = isChecked(data, h.id, today);
      cb.addEventListener('change', function () {
        data = toggleCheck(data, h.id, todayString());
        saveData(data);
        render();
      });
      var lab = document.createElement('label');
      lab.htmlFor = cb.id;
      lab.textContent = h.name;
      var sp = document.createElement('span');
      sp.id = 'streak-' + h.id;
      sp.className = 'streak';
      sp.textContent = 'Streak: ' + getStreak(data, h.id, today);
      li.appendChild(cb);
      li.appendChild(lab);
      li.appendChild(sp);
      list.appendChild(li);
    });
  }

  function add() {
    data = addHabit(data, input.value);
    saveData(data);
    input.value = '';
    render();
  }

  btn.addEventListener('click', add);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { e.preventDefault(); add(); }
  });

  render();
})();

